1	// Package placement parses raw placement request bodies into the input
2	// object accepted by service.Accept. It is a standalone entry point: it has
3	// no dependency on the HTTP transport, opens no database, and performs no
4	// scheduling or writes. The HTTP API and direct callers share exactly these
5	// strict rules.
6	package placement
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"errors"
12		"io"
13		"strconv"
14		"strings"
15	
16		"github.com/Bob-xisuke/orb-scheduler-core/internal/store"
17	)
18	
19	// ErrInvalidPlacementInput is the single sentinel returned for every parse
20	// failure: malformed JSON, a non-object root, trailing data, unknown or
21	// duplicate member names, missing required fields, explicit nulls, type or
22	// range errors, and duplicate node names. Callers classify failures with
23	// errors.Is; a failed parse never yields a partial input object.
24	var ErrInvalidPlacementInput = errors.New("invalid placement input")
25	
26	// ---------------------------------------------------------------------------
27	// Strict request parsing.
28	//
29	// readStrictObject/readObjectMembers below are the single definition of the
30	// object-member rules shared by the top-level request body and every nested
31	// object (resources, node, selector, labels):
32	//   - the value is exactly one JSON object,
33	//   - no unknown or duplicate member names (member names are compared after
34	//     escape decoding, so a name also collides with its escaped spellings),
35	//   - each value is captured raw for the field-specific rules that follow.
36	//
37	// ParsePlacementInput adds the root-level rules on top of that shared walk:
38	// no trailing data after the root object, every required member present, each
39	// field's declared JSON type and range (null is never accepted where a value
40	// is required; omitted selector/labels default to {}), and unique node names.
41	// ---------------------------------------------------------------------------
42	
43	var topLevelFields = map[string]bool{
44		"namespace": true,
45		"name":      true,
46		"queue":     true,
47		"priority":  true,
48		"resources": true,
49		"selector":  true,
50		"nodes":     true,
51	}
52	
53	var resourceFields = map[string]bool{"cpu": true, "memory": true}
54	
55	var nodeFields = map[string]bool{
56		"name":   true,
57		"cpu":    true,
58		"memory": true,
59		"labels": true,
60	}
61	
62	// ParsePlacementInput decodes one placement request body. On success it
63	// returns the complete input object, ready for service.Accept: every input
64	// field keeps its submitted value, the node array keeps its order, omitted
65	// selector and node labels are filled as empty objects, and an empty nodes
66	// array stays an empty array. On any rule violation it returns nil and an
67	// error matching errors.Is(err, ErrInvalidPlacementInput).
68	func ParsePlacementInput(body []byte) (*store.Placement, error) {
69		dec := json.NewDecoder(bytes.NewReader(body))
70	
71		fields, err := readStrictObject(dec, topLevelFields)
72		if err != nil {
73			return nil, err
74		}
75		if _, err := dec.Token(); !errors.Is(err, io.EOF) {
76			return nil, ErrInvalidPlacementInput // trailing data
77		}
78	
79		for _, required := range []string{"namespace", "name", "queue", "priority", "resources", "nodes"} {
80			if _, ok := fields[required]; !ok {
81				return nil, ErrInvalidPlacementInput
82			}
83		}
84	
85		p := &store.Placement{}
86		if p.Namespace, err = parseTrimmedString(fields["namespace"]); err != nil {
87			return nil, err
88		}
89		if p.Name, err = parseTrimmedString(fields["name"]); err != nil {
90			return nil, err
91		}
92		if p.Queue, err = parseTrimmedString(fields["queue"]); err != nil {
93			return nil, err
94		}
95		priority, err := parseBoundedInt(fields["priority"], 32)
96		if err != nil {
97			return nil, err
98		}
99		p.Priority = int32(priority)
100		if p.Resources, err = parseResources(fields["resources"]); err != nil {
101			return nil, err
102		}
103		if p.Nodes, err = parseNodes(fields["nodes"]); err != nil {
104			return nil, err
105		}
106		p.Selector = map[string]string{}
107		if raw, ok := fields["selector"]; ok {
108			if p.Selector, err = parseStringMap(raw); err != nil {
109				return nil, err
110			}
111		}
112		return p, nil
113	}
114	
115	func parseResources(raw json.RawMessage) (store.Resources, error) {
116		var r store.Resources
117		obj, err := parseStrictObject(raw, resourceFields)
118		if err != nil {
119			return r, err
120		}
121		cpuRaw, ok := obj["cpu"]
122		if !ok {
123			return r, ErrInvalidPlacementInput
124		}
125		memoryRaw, ok := obj["memory"]
126		if !ok {
127			return r, ErrInvalidPlacementInput
128		}
129		cpu, err := parseBoundedInt(cpuRaw, 64)
130		if err != nil || cpu <= 0 {
131			return r, ErrInvalidPlacementInput
132		}
133		memory, err := parseBoundedInt(memoryRaw, 64)
134		if err != nil || memory <= 0 {
135			return r, ErrInvalidPlacementInput
136		}
137		return store.Resources{CPU: cpu, Memory: memory}, nil
138	}
139	
140	func parseNodes(raw json.RawMessage) ([]store.Node, error) {
141		if isNull(raw) {
142			return nil, ErrInvalidPlacementInput
143		}
144		dec := json.NewDecoder(bytes.NewReader(raw))
145		tok, err := dec.Token()
146		if err != nil {
147			return nil, ErrInvalidPlacementInput
148		}
149		if d, ok := tok.(json.Delim); !ok || d != '[' {
150			return nil, ErrInvalidPlacementInput
151		}
152	
153		nodes := []store.Node{}
154		names := map[string]bool{}
155		for dec.More() {
156			var elem json.RawMessage
157			if err := dec.Decode(&elem); err != nil {
158				return nil, ErrInvalidPlacementInput
159			}
160			obj, err := parseStrictObject(elem, nodeFields)
161			if err != nil {
162				return nil, err
163			}
164			nameRaw, ok := obj["name"]
165			if !ok {
166				return nil, ErrInvalidPlacementInput
167			}
168			cpuRaw, ok := obj["cpu"]
169			if !ok {
170				return nil, ErrInvalidPlacementInput
171			}
172			memoryRaw, ok := obj["memory"]
173			if !ok {
174				return nil, ErrInvalidPlacementInput
175			}
176			name, err := parseTrimmedString(nameRaw)
177			if err != nil {
178				return nil, err
179			}
180			cpu, err := parseBoundedInt(cpuRaw, 64)
181			if err != nil || cpu < 0 {
182				return nil, ErrInvalidPlacementInput
183			}
184			memory, err := parseBoundedInt(memoryRaw, 64)
185			if err != nil || memory < 0 {
186				return nil, ErrInvalidPlacementInput
187			}
188			labels := map[string]string{}
189			if labelRaw, ok := obj["labels"]; ok {
190				labels, err = parseStringMap(labelRaw)
191				if err != nil {
192					return nil, err
193				}
194			}
195			if names[name] {
196				return nil, ErrInvalidPlacementInput
197			}
198			names[name] = true
199			nodes = append(nodes, store.Node{Name: name, CPU: cpu, Memory: memory, Labels: labels})
200		}
201		if _, err := dec.Token(); err != nil {
202			return nil, ErrInvalidPlacementInput // closing ']'
203		}
204		return nodes, nil
205	}
206	
207	// readStrictObject consumes exactly one JSON object from dec and returns its
208	// members with their values still raw. Together with readObjectMembers it is
209	// the single definition of the member rules: member names are restricted to
210	// allowed (nil allows any names), and unknown and duplicate names are
211	// rejected before the duplicate value can overwrite anything.
212	func readStrictObject(dec *json.Decoder, allowed map[string]bool) (map[string]json.RawMessage, error) {
213		tok, err := dec.Token()
214		if err != nil {
215			return nil, ErrInvalidPlacementInput
216		}
217		if d, ok := tok.(json.Delim); !ok || d != '{' {
218			return nil, ErrInvalidPlacementInput
219		}
220		return readObjectMembers(dec, allowed)
221	}
222	
223	// parseStrictObject applies the shared member rules to a raw nested object.
224	func parseStrictObject(raw json.RawMessage, allowed map[string]bool) (map[string]json.RawMessage, error) {
225		if isNull(raw) {
226			return nil, ErrInvalidPlacementInput
227		}
228		return readStrictObject(json.NewDecoder(bytes.NewReader(raw)), allowed)
229	}
230	
231	// parseStringMap decodes an object with arbitrary string keys and string
232	// values; null or non-string values are rejected.
233	func parseStringMap(raw json.RawMessage) (map[string]string, error) {
234		raws, err := parseStrictObject(raw, nil)
235		if err != nil {
236			return nil, err
237		}
238		out := map[string]string{}
239		for key, value := range raws {
240			s, err := parseJSONString(value)
241			if err != nil {
242				return nil, err
243			}
244			out[key] = s
245		}
246		return out, nil
247	}
248	
249	func readObjectMembers(dec *json.Decoder, allowed map[string]bool) (map[string]json.RawMessage, error) {
250		out := map[string]json.RawMessage{}
251		for dec.More() {
252			keyTok, err := dec.Token()
253			if err != nil {
254				return nil, ErrInvalidPlacementInput
255			}
256			key, ok := keyTok.(string)
257			if !ok {
258				return nil, ErrInvalidPlacementInput
259			}
260			if allowed != nil && !allowed[key] {
261				return nil, ErrInvalidPlacementInput
262			}
263			if _, dup := out[key]; dup {
264				return nil, ErrInvalidPlacementInput
265			}
266			var value json.RawMessage
267			if err := dec.Decode(&value); err != nil {
268				return nil, ErrInvalidPlacementInput
269			}
270			out[key] = value
271		}
272		if _, err := dec.Token(); err != nil {
273			return nil, ErrInvalidPlacementInput // closing '}'
274		}
275		return out, nil
276	}
277	
278	// parseTrimmedString accepts a JSON string that is non-empty and has no
279	// leading or trailing Unicode whitespace.
280	func parseTrimmedString(raw json.RawMessage) (string, error) {
281		s, err := parseJSONString(raw)
282		if err != nil {
283			return "", err
284		}
285		if s == "" || s != strings.TrimSpace(s) {
286			return "", ErrInvalidPlacementInput
287		}
288		return s, nil
289	}
290	
291	func parseJSONString(raw json.RawMessage) (string, error) {
292		if isNull(raw) {
293			return "", ErrInvalidPlacementInput
294		}
295		var s string
296		if err := json.Unmarshal(raw, &s); err != nil {
297			return "", ErrInvalidPlacementInput
298		}
299		return s, nil
300	}
301	
302	// parseBoundedInt accepts an integral JSON number without fraction or exponent
303	// that fits a signed integer of the given bit size (32 or 64).
304	func parseBoundedInt(raw json.RawMessage, bitSize int) (int64, error) {
305		if isNull(raw) {
306			return 0, ErrInvalidPlacementInput
307		}
308		dec := json.NewDecoder(bytes.NewReader(raw))
309		dec.UseNumber()
310		var value any
311		if err := dec.Decode(&value); err != nil {
312			return 0, ErrInvalidPlacementInput
313		}
314		number, ok := value.(json.Number)
315		if !ok {
316			return 0, ErrInvalidPlacementInput
317		}
318		n, err := strconv.ParseInt(number.String(), 10, bitSize)
319		if err != nil {
320			return 0, ErrInvalidPlacementInput
321		}
322		return n, nil
323	}
324	
325	func isNull(raw json.RawMessage) bool {
326		return bytes.Equal(bytes.TrimSpace(raw), []byte("null"))
327	}
