46	func decodeBody(t *testing.T, rec *httptest.ResponseRecorder) map[string]any {
47		t.Helper()
48		var out map[string]any
49		if err := json.Unmarshal(rec.Body.Bytes(), &out); err != nil {
50			t.Fatalf("decode %q: %v", rec.Body.String(), err)
51		}
52		return out
53	}
