123				t.Fatalf("first = %d: %s", first.Code, first.Body.String())
124			}
125			rec, outcome := acceptViaService(t, svc, withDefaults)
126			if outcome != service.Identical {
127				t.Fatalf("outcome = %d, want Identical", outcome)
128			}
129			expectSameRecordAsHTTP(t, rec, first.Body.String())
130		})
131	
132		t.Run("direct minimal then http defaults", func(t *testing.T) {
133			st, h := newTestRouter(t)
134			svc := service.New(st)
135			rec, outcome := acceptViaService(t, svc, minimal)
136			if outcome != service.Created {
