138			}
139			second := postPlacement(t, h, withDefaults)
140			if second.Code != http.StatusOK {
141				t.Fatalf("http retry = %d, want 200: %s", second.Code, second.Body.String())
142			}
143			expectSameRecordAsHTTP(t, rec, second.Body.String())
144		})
145	}
146	
147	// Reordering only the node array produces the same scheduling result but is a
148	// content conflict through both channels, and the original survives in GET.
149	func TestCrossCheckNodeReorderConflictAcrossChannels(t *testing.T) {
150		body := `{
151		  "namespace": "ns", "name": "job", "queue": "q", "priority": 1,
152		  "resources": {"cpu": 1, "memory": 1},
153		  "nodes": [
154		    {"name": "n1", "cpu": 10, "memory": 10, "labels": {}},
