192		httpConflict := postPlacement(t, h, reordered)
193		expectErrorCode(t, httpConflict, http.StatusConflict, "PlacementConflictError")
194	}
195	
196	// A rejected decision produced through the independent entry point is stored
197	// and reads back through HTTP unchanged, including null node and the reason.
198	func TestCrossCheckRejectedRecordQueryableOverHTTP(t *testing.T) {
199		body := `{
200		  "namespace": "team-a", "name": "job-2", "queue": "default", "priority": -1,
201		  "resources": {"cpu": 2000, "memory": 256},
